-- name: Ry`Gorr_Emissary
-- Generated by scripts/quests/coldain-rings.mjs from coldain_rings.json.
-- P99: https://wiki.project1999.com/Coldain_Ring_Quests
-- Reference: https://github.com/EQMacEmu/quests/blob/11c46f912740eaa1d10cf6658a80cf756defd4d8/eastwastes/encounters/rodrick.lua
-- P99 says a few minutes; IdleQuest uses three unengaged minutes at the existing emissary placement. No authored emissary patrol route exists in this database. TAKP route/dialogue choreography is not claimed. Rodrick retains the local level-40 variant and placement; TAKP uses its level-41 NPC ID. His 200-second stay pauses during combat as in TAKP.
function event_spawn(e)
  eq.set_timer("meeting", 180000)
end
function event_combat(e)
  if e.joined then eq.pause_timer("meeting") else eq.resume_timer("meeting") end
end
function event_timer(e)
  if e.timer ~= "meeting" then return end
  -- The current actor state also protects a due callback racing combat entry.
  if e.self:IsEngaged() then eq.pause_timer("meeting"); return end
  eq.stop_timer("meeting")
  eq.unique_spawn(116140, 0, 0, 1056, -3406, 149.130005, 390)
  -- Finish the stationary encounter approximation through the ordinary authored
  -- respawn pool. Otherwise only a fresh character could ever see a new meeting.
  eq.depop_with_timer()
end
function event_death_complete(e) eq.stop_timer("meeting") end
